import { Object3D, Vector3, Euler } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} PrimitiveConfig
 * @property {string} name
 * @property {Object} params
 */

/**
 * @typedef {Object} NodeConfig
 * @property {{ x: number, y: number, z: number }} position
 * @property {{ x: number, y: number, z: number }} rotation
 * @property {{ x: number, y: number, z: number }} scale
 * @property {{ meshUrl?: string }} assets
 * @property {PrimitiveConfig[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader                // returns a cached GLTF (with .scene)
 * @property {Record<string, (obj:Object3D, params:any)=>void>} primitives
 * @property {(event:string)=>void} [emit]                // optional event emitter
 */

/**
 * Creates a thumbnail card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Object3D();

  // Apply placement
  if (config.position) root.position.set(config.position.x, config.position.y, config.position.z);
  if (config.rotation) root.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  if (config.scale) root.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // Load mesh
  if (config.assets && config.assets.meshUrl) {
    const gltf = ctx.glbLoader(config.assets.meshUrl);
    if (gltf && gltf.scene) {
      const mesh = gltf.scene.clone();
      root.add(mesh);
    }
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Store original Y for hover animation
  const originalY = root.position.y;

  // GSAP timeline tracking
  const _timelines = [];

  // Event handlers container
  root.userData.handlers = {};

  // Hover (rise‑in) handler
  root.userData.handlers.hover = () => {
    const tl = gsap.to(root.position, {
      y: originalY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
    _timelines.push(tl);
  };

  // Click (emit) handler
  root.userData.handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-features.select');
    }
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    _timelines.forEach((t) => t.kill());
    _timelines.length = 0;

    // Dispose geometries and materials
    root.traverse((obj) => {
      if (obj.geometry) {
        obj.geometry.dispose();
      }
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
